<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarNodo, guardarNodo, obtenerEstructura, type ComponenteBgc, type CriterioBgc, type EstandarBgc, type PilarBgc } from '../services/bgc'
type NodeType='pilar'|'estandar'|'componente'|'criterio'
const pilares=ref<PilarBgc[]>([]),tipos=ref<Array<{id:number;nombre:string}>>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),nodeType=ref<NodeType>('pilar'),editing=ref<number|null>(null),expanded=ref<number[]>([])
const form=reactive({nombre:'',descripcion:'',estado:true,pilar_id:0,estandar_id:0,componente_id:0,tipo_criterio_id:0})
async function load(){loading.value=true;try{const r=await obtenerEstructura();pilares.value=r.pilares;tipos.value=r.tipos_criterio;if(!expanded.value.length)expanded.value=r.pilares.map(p=>p.id)}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo cargar la estructura.'}finally{loading.value=false}}
function open(type:NodeType,parent?:PilarBgc|EstandarBgc|ComponenteBgc,item?:PilarBgc|EstandarBgc|ComponenteBgc|CriterioBgc){nodeType.value=type;editing.value=item?.id||null;Object.assign(form,{nombre:item?.nombre||'',descripcion:item?.descripcion||'',estado:item?.estado??true,pilar_id:type==='estandar'?(parent?.id||0):0,estandar_id:type==='componente'?(parent?.id||0):0,componente_id:type==='criterio'?(parent?.id||0):0,tipo_criterio_id:type==='criterio'?(item as CriterioBgc)?.tipo_criterio?.id||0:0});modal.value=true}
async function save(){if(!form.nombre.trim()){error.value='Ingrese el nombre.';return}saving.value=true;try{await guardarNodo(nodeType.value,editing.value,{...form});success.value=`${nodeType.value} guardado correctamente.`;modal.value=false;await load()}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo guardar.'}finally{saving.value=false}}
async function remove(type:NodeType,id:number){if(!confirm('¿Desactivar o eliminar este elemento?'))return;try{await eliminarNodo(type,id);await load()}catch(cause){error.value=cause instanceof Error?cause.message:'No se pudo eliminar.'}}
function toggle(id:number){expanded.value=expanded.value.includes(id)?expanded.value.filter(x=>x!==id):[...expanded.value,id]}
onMounted(load)
</script>
<template><div class="bgc"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/institucional">Institucional</RouterLink> / Buen Gobierno / Estructura</nav><header class="hero"><div class="mark">BGC</div><div><small>Buen Gobierno Corporativo</small><h1>Estructura BGC</h1><p>Administra la jerarquía de pilares, estándares, componentes y criterios.</p></div><strong>{{pilares.length}} pilares</strong><button @click="open('pilar')">+ Nuevo pilar</button></header><div v-if="success" class="flash">✓ {{success}}</div><div v-if="error" class="flash error">{{error}}</div><div v-if="loading" class="notice">Cargando estructura…</div><div v-else-if="!pilares.length" class="notice">No hay pilares registrados.</div><section v-else class="tree"><article v-for="p in pilares" :key="p.id" :class="{inactive:!p.estado}"><header @click="toggle(p.id)"><button class="chevron">{{expanded.includes(p.id)?'−':'+'}}</button><div><small>Pilar</small><h2>{{p.nombre}}</h2><p>{{p.descripcion}}</p></div><span>{{p.estandares.length}} estándares</span><div class="actions" @click.stop><button @click="open('estandar',p)">+ Estándar</button><button @click="open('pilar',undefined,p)">Editar</button><button class="delete" @click="remove('pilar',p.id)">Eliminar</button></div></header><div v-if="expanded.includes(p.id)" class="standards"><section v-for="e in p.estandares" :key="e.id"><header><div><small>Estándar</small><h3>{{e.nombre}}</h3><p>{{e.descripcion}}</p></div><div class="actions"><button @click="open('componente',e)">+ Componente</button><button @click="open('estandar',p,e)">Editar</button><button class="delete" @click="remove('estandar',e.id)">×</button></div></header><div class="components"><article v-for="c in e.componentes" :key="c.id"><header><div><small>Componente</small><h4>{{c.nombre}}</h4><p>{{c.descripcion}}</p></div><div class="actions"><button @click="open('criterio',c)">+ Criterio</button><button @click="open('componente',e,c)">Editar</button></div></header><ul><li v-for="cr in c.criterios" :key="cr.id"><div><small>{{cr.tipo_criterio?.nombre||'Sin tipo'}}</small><b>{{cr.nombre}}</b><span>{{cr.descripcion}}</span></div><em>{{cr.evidencias_count||0}} evidencias</em><button @click="open('criterio',c,cr)">Editar</button><button class="delete" @click="remove('criterio',cr.id)">×</button></li></ul></article></div></section></div></article></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><section class="modal"><header><div><small>Estructura BGC</small><h2>{{editing?'Editar':'Registrar'}} {{nodeType}}</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="save"><label><span>Nombre *</span><input v-model.trim="form.nombre"></label><label><span>Descripción</span><textarea v-model.trim="form.descripcion" rows="3"></textarea></label><label v-if="nodeType==='criterio'"><span>Tipo de criterio *</span><select v-model="form.tipo_criterio_id"><option :value="0" disabled>Seleccione</option><option v-for="t in tipos" :key="t.id" :value="t.id">{{t.nombre}}</option></select></label><label class="check"><input v-model="form.estado" type="checkbox"> Elemento activo</label><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar'}}</button></footer></form></section></div></div></template>
<style scoped>
.bgc{--accent:#7257c8;color:#35464e}nav{margin-bottom:17px;color:#98a4aa;font-size:.7rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--accent);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.modal small,.tree small{color:var(--accent);font-size:.56rem;font-weight:700;text-transform:uppercase}.hero h1{margin:2px 0;font-size:1.38rem}.hero p{margin:0;color:#7d898f;font-size:.72rem}.hero>strong{margin-left:auto;font-size:.63rem}.hero button,.actions button,.modal footer button{padding:7px 10px;border:1px solid var(--accent);border-radius:6px;color:#fff;background:var(--accent);font-size:.58rem}.flash{margin-top:14px;padding:11px;border:1px solid #b9dfce;border-radius:8px;color:#286b50;background:#eff9f4;font-size:.67rem}.flash.error{color:#a13f43;border-color:#efcaca;background:#fff4f4}.notice{margin-top:16px;padding:45px;text-align:center;border:1px dashed #cbd6dc;border-radius:10px;background:#fff;font-size:.69rem}.tree{margin-top:16px}.tree>article{margin-bottom:12px;border:1px solid #ddd8ed;border-left:4px solid var(--accent);border-radius:10px;background:#fff}.tree>article>header{padding:14px;display:flex;align-items:center;gap:10px;cursor:pointer}.chevron{width:28px;height:28px;border:0;border-radius:50%;color:var(--accent);background:#eeeafa}.tree h2,.tree h3,.tree h4,.tree p{margin:2px 0}.tree h2{font-size:.82rem}.tree h3{font-size:.75rem}.tree h4{font-size:.68rem}.tree p{color:#7d898f;font-size:.57rem}.tree>article>header>span{margin-left:auto;font-size:.58rem}.actions{display:flex;gap:4px}.actions .delete,.delete{border-color:#bd5050;background:#bd5050}.standards{padding:0 14px 14px}.standards>section{margin-top:8px;border:1px solid #e4e1ed;border-radius:8px;background:#f9f8fc}.standards>section>header,.components article>header{padding:11px;display:flex}.standards .actions,.components .actions{margin-left:auto}.components{padding:0 10px 10px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.components>article{border:1px solid #e2e5e8;border-radius:7px;background:#fff}.components ul{margin:0;padding:0 10px 10px;list-style:none}.components li{padding:8px 0;display:flex;align-items:center;gap:6px;border-top:1px solid #edf0f2}.components li div{flex:1}.components li b,.components li span{display:block;font-size:.57rem}.components li span{color:#7d898f}.components li em{font-size:.52rem;font-style:normal}.components li button{border:0;color:var(--accent);background:none;font-size:.55rem}.components li .delete{color:#bd5050}.inactive{opacity:.65}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#15283a88}.modal{width:min(100%,500px);border-radius:12px;background:#fff}.modal>header{padding:18px 20px;display:flex;border-bottom:1px solid #e5eaed}.modal h2{margin:2px 0;font-size:1rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.modal form{padding:20px}.modal label{display:block;margin-bottom:13px}.modal label>span{display:block;margin-bottom:5px;font-size:.62rem}input,select,textarea{width:100%;padding:9px;border:1px solid #dae2e6;border-radius:7px;font:inherit;font-size:.67rem}.check input{width:auto}.modal footer{display:flex;justify-content:flex-end;gap:7px}.clear{color:#68757c!important;border-color:#d5dee2!important;background:#fff!important}@media(max-width:800px){.components{grid-template-columns:1fr}.tree>article>header{flex-wrap:wrap}.tree>article>header>span{margin-left:0}.actions{width:100%}.hero{flex-wrap:wrap}.hero>strong{margin:0}}
</style>
